SELECT CASE WHEN salary >= 144000 THEN 'high' WHEN salary >= 73000 THEN 'mid' ELSE 'low' END AS salary_bucket, MAX(salary) - MIN(salary) AS salary_range, SUM(salary) AS total_salary, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list FROM employees WHERE full_name IS NULL AND (job_title = 'Director' OR is_remote) GROUP BY CASE WHEN salary >= 144000 THEN 'high' WHEN salary >= 73000 THEN 'mid' ELSE 'low' END;
